import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {searchUrl, subnetsUrl} from '../helpers/urls'
import type {NetworkSettingsResult, SubnetResult} from '../types/payloads'

interface SearchResponse {
  results: NetworkSettingsResult[]
}

interface SubnetsResponse {
  results: SubnetResult[]
}

interface ErrorResponse {
  error: string
}

export async function searchNetworkSettings(searchIds: string): Promise<{
  results?: NetworkSettingsResult[]
  error?: string
}> {
  const url = `${searchUrl()}?search_ids=${encodeURIComponent(searchIds)}`

  if (searchIds.trim() === '*') {
    return {results: []}
  }

  try {
    const response = await verifiedFetchJSON(url)

    if (!response.ok) {
      const errorData: ErrorResponse = await response.json()
      return {error: errorData.error || 'An error occurred while searching'}
    }

    const data: SearchResponse = await response.json()
    // eslint-disable-next-line no-console
    console.log('Search results:', data.results)
    return {results: data.results}
  } catch {
    return {error: 'An unexpected error occurred'}
  }
}

