export async function searchSubnets(subnetIds: string): Promise<{
  results?: SubnetResult[]
  error?: string
}> {
  const url = `${subnetsUrl()}?subnet_ids=${encodeURIComponent(subnetIds)}`

  if (subnetIds.trim() === '*') {
    return {results: []}
  }

  if (USE_MOCK_SUBNET_DATA) {
    return {results: MOCK_SUBNET_RESULTS}
  }

  try {
    const response = await verifiedFetchJSON(url)

    if (!response.ok) {
      const errorData: ErrorResponse = await response.json()
      return {error: errorData.error || 'An error occurred while searching subnets'}
    }

    const data: SubnetsResponse = await response.json()

    const firstResult = data.results[0]
    if (typeof firstResult === 'string') {
      // If the first result is a string, it's likely an error message instead of a valid subnet result
      return {error: firstResult}
    }

    return {results: data.results}
  } catch {
    return {error: 'An unexpected error occurred'}
  }
}
